		return trace.BadParameter("missing required parameter DatabaseName")
	}

	if p.Username == "" {
		return trace.BadParameter("missing required parameter Username")
	}

	if p.Port == 0 {
		return trace.BadParameter("missing required parameter Port")
	}

	if p.Host == "" {
		p.Host = "localhost"
	}

	return nil
}
